import { StyleFn } from "../elements/StyleFn";

/**
 * reusable focus styles
 * @param theme
 * @returns
 */
export const focus: StyleFn = (theme, mode) => {
  const { color } = theme;
  const focusColor = color.border.accent.focus[mode];

  const browserReset = {
    // Remove Firefox dotted outline
    "&::-moz-focus-inner": {
      borderStyle: "none",
    },
  };

  return {
    focusDefault: {
      ...browserReset,
      border: "2px solid transparent",
      "&:focus-visible": {
        outline: "none",
        border: `2px solid ${focusColor}`,
      },
    },
    focusWithPseudo: ({
      colorForce = "",
      pseudo = "after",
      focusSelector = "focus-visible",
      radius = "6px",
      offset = 4,
      width = "",
      borderWidth = "2px",
      transparentBorder = true,
    } = {}) => ({
      ...browserReset,
      // elements with borders need spacing between focus border
      position: "relative",
      border: transparentBorder ? `${borderWidth} solid transparent` : undefined,
      [`&:${focusSelector}`]: { outline: "none" },
      [`&:${focusSelector}:${pseudo}`]: {
        content: '""',
        position: "absolute",
        top: -offset,
        left: -offset,
        right: -offset,
        bottom: -offset,
        border: `${borderWidth} solid ${colorForce === "" ? focusColor : colorForce}`,
        borderRadius: radius,
        ...(width !== "" && { width }),
      },
    }),
  };
};
